import sys,importlib
from pathlib import Path
sys.path.insert(0,str(Path(__file__).resolve().parent))
def supplementary():
 import io,unittest,os
 from workflows.expansion.alpha_runtime_v1 import common as Q
 from workflows.expansion.alpha_runtime_v1.guard import Guard
 path=Path(sys.argv[sys.argv.index('--plan')+1]);plan=Q.load(path);guard=Guard(plan)
 try:
  modules=[importlib.import_module(name)for name in ('workflows.expansion.uff3_alpha_runtime_v1.test_quality_metadata','workflows.expansion.uff3_alpha_runtime_v1.test_entry')]
  for module in modules:Q.need(Q.reference(module.__file__)in plan['code_references'],'Actual supplementary source pinned')
  suite=unittest.TestSuite(unittest.defaultTestLoader.loadTestsFromModule(m)for m in modules);log=io.StringIO();r=unittest.TextTestRunner(stream=log,verbosity=2).run(suite)
  Q.write(path.parent/'supplementary_uff_metadata_tests.json',dict(schema='ROOT_ALPHA_UFF_ADAPTER_NATIVE_METADATA_FIXTURES_V1',tests=r.testsRun,errors=len(r.errors),failures=len(r.failures),skips=len(r.skipped),transcript=log.getvalue(),source_references=[Q.reference(m.__file__)for m in modules],job_id=os.environ['SLURM_JOB_ID'],scope='METADATA_FIXTURES_ONLY_NO_UFF_GEOMETRY_OR_DATASET_CLAIM'))
  Q.need(r.testsRun==10 and r.wasSuccessful()and not r.skipped,'Actual ten supplementary metadata fixtures required');guard.sample();guard.check()
 finally:guard.close()
def main():
 module=sys.argv.pop(1);importlib.import_module(module).main()
 if module=='workflows.expansion.alpha_typed_rank_v1.fixture_bundle':supplementary()
if __name__=='__main__':main()
